checks.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import { gunzipSync } from 'node:zlib';
import { spawnSync } from 'node:child_process';
const source = fs.readFileSync('scripts/deploy.sh', 'utf8');
const guard = "#!/bin/bash\n\nset -e\n\nif [ \"$#\" -ne 1 ]; then\n    builtin printf '%s\\n' 'Usage: bash scripts/deploy.sh default|staging|production' >&2\n    exit 2\nfi\n\ncase \"$1\" in\n    default|staging|production) ENVIRONMENT=$1 ;;\n    *)\n        builtin printf '%s\\n' 'Usage: bash scripts/deploy.sh default|staging|production' >&2\n        exit 2\n        ;;\nesac\n";
assert.equal(source.slice(0, guard.length), guard, 'exact builtin-only first guard');
const baseline = JSON.parse(fs.readFileSync('docs/remediation/design/W08.03/baseline.json', 'utf8'));
const before = gunzipSync(Buffer.from(baseline.owned[0].content_gzip_base64, 'base64')).toString('utf8');
const oldPrefix = '#!/bin/bash\n\nset -e\n\nENVIRONMENT=${1:-default}\n';
assert.ok(before.startsWith(oldPrefix));
const suffix = before.slice(oldPrefix.length)
  .replace('wrangler secret list 2>/dev/null', "wrangler secret list --env '' 2>/dev/null")
  .replace('    wrangler deploy\n', "    wrangler deploy --env ''\n");
assert.equal(source.slice(guard.length), suffix, 'only two admitted default argv changes');
const env = { PATH: '', CLOUDFLARE_ENV: 'production' };
const parsed = spawnSync('/bin/bash', ['--noprofile', '--norc', '-n', 'scripts/deploy.sh'], { env, encoding: 'utf8' });
assert.equal(parsed.error, undefined); assert.equal(parsed.status, 0, parsed.stderr);
const isolated = source.slice(0, guard.length) + '\nbuiltin printf \'%s\\n\' "$ENVIRONMENT"\n';
const rejected = [[], [''], ['prodution'], ['unknown'], ['Production'], [' default'], ['default '], ['--help'], ['default', 'extra'], ['staging', ''], ['production', 'default']];
for (const args of rejected) {
  const r = spawnSync('/bin/bash', ['--noprofile', '--norc', '-c', isolated, 'guard-only', ...args], { env, encoding: 'utf8' });
  assert.equal(r.error, undefined); assert.equal(r.status, 2); assert.equal(r.stdout, '');
  assert.equal(r.stderr, 'Usage: bash scripts/deploy.sh default|staging|production\n');
}
for (const selected of ['default', 'staging', 'production']) {
  const r = spawnSync('/bin/bash', ['--noprofile', '--norc', '-c', isolated, 'guard-only', selected], { env, encoding: 'utf8' });
  assert.equal(r.error, undefined); assert.equal(r.status, 0); assert.equal(r.stdout, selected + '\n'); assert.equal(r.stderr, '');
}
console.log('PASS: exact first guard; 11 rejected/3 selected isolated cases; bash syntax; entire suffix preserved except two explicit default argv changes. Deployment body and Wrangler never executed.');
NODE
